'use strict';

/**
 * The staff guide ("How TDOT works") served at /admin/guide (Faran 2026-10-30).
 *
 * Two files, both generated by the staff-guide build pipeline:
 *   src/staffGuide/guide.html       — the page, with NO guide content in it
 *   src/staffGuide/guide-data.json  — the content, sent only to signed-in staff
 * Read once and kept in memory; a missing file serves a short notice instead
 * of failing the server.
 */

const fs = require('fs');
const path = require('path');

const DIR = path.join(__dirname, '..', 'staffGuide');
let cache = null;

function load() {
  if (cache) return cache;
  const read = (f) => { try { return fs.readFileSync(path.join(DIR, f), 'utf8'); } catch (_) { return ''; } };
  cache = { page: read('guide.html'), data: read('guide-data.json') };
  return cache;
}

const MISSING_PAGE = '<!doctype html><meta charset="utf-8"><title>Staff guide</title><p style="font:15px system-ui;margin:40px">The staff guide is not available on this server yet.</p>';

function page() { return load().page || MISSING_PAGE; }
function data() { return load().data || '{}'; }

module.exports = { page, data, DIR };
